procedure PhysioSessionStats {
  about "Get session stats for Friday"
  policy PhysioPolicy
  sheet Sessions "Sessions" { patient: Text, mobile: Phone, session_at: DateTime, therapist: Text, status: Text, injury: Text private }
  trigger every Friday at 17:30

  let today = today()
  let seven_days_ago = today - 7 days

  let done = filter Sessions where session_at >= seven_days_ago and session_at < today and status == "done"
  let no_show = filter Sessions where session_at >= seven_days_ago and session_at < today and status == "no-show"

  let count_done = summarize count of done
  let count_no_show = summarize count of no_show

  stop "count_done: {count_done}, count_no_show: {count_no_show}"
}

