procedure PhysioSessionBooking {
  about "Book sessions based on patient input"
  policy PhysioPolicy
  sheet Sessions "Sessions" { patient: Text, mobile: Phone, session_at: DateTime, therapist: Text, status: Text, injury: Text private }
  calendar Rooms "Rooms"

  trigger when new row r in Sessions

  if r.therapist is empty {
    notify owner "No therapist provided for session {r.patient}. Please specify."
    stop "no therapist"
  }

  let room = find Rooms where title == r.patient else skip
  if room is not found {
    notify owner "No room found for session {r.patient}. Please create one."
    stop "no room"
  }

  append Rooms { title: r.patient, start: r.session_at, duration: 45 minutes }
  let m = draft sms to r.mobile: "Hi {r.patient}, your session has been booked for {time_of(r.session_at)}. I approve this."
  let ok = request approval of m from owner timeout 2 hours else stop "message not approved"
  send ok
  update r set status = "confirmed"
}
```

