procedure DrivingLessonReminder {
  about "Send lesson reminder to active learners"
  policy DrivingPolicy
  sheet Learners "Learners" { learner: Text, phone: Phone, lessons_left: Number, test_date: Date, status: Text, license_no: Text private }
  trigger every monday at 10:00

  let all = fetch Learners
  let learners = filter all where lessons_left <= 2 and status == "active"
  let n = summarize count of learners
  if n > 25 {
    notify owner "Cannot send more than 25 learners at once. Only {n} are eligible."
    stop "exceeds batch limit"
  }
  let msgs = draft each r in learners up to 25 sms to r.phone: "Hi {r.learner}, you have {r.lessons_left} lessons left. Get a new package today! 🚗"
  let ok = request batch approval of msgs from owner timeout 1 hour else stop "batch not approved"
  send ok
}

