procedure CoffeeOrderScheduler {
  about "Order beans based on reorder points"
  policy CoffeePolicy
  sheet Beans "Beans" { blend: Text, bags: Number, reorder_at: Number, order_bags: Number, roaster: Text, price_per_bag: Money }
  trigger every day at 6:30

  let all = fetch Beans
  let needs_order = filter all where bags <= reorder_at
  let orders = group by blend of needs_order
  let valid_orders = filter orders where sum(order_bags * price_per_bag) <= $120

  for each blend in valid_orders {
    let order_amount = sum(order_bags * price_per_bag)
    let m = draft sms to blend.roaster: "Order of {order_amount} for {blend} has been placed."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
  }

  let invalid_orders = filter orders where sum(order_bags * price_per_bag) > $120
  for each blend in invalid_orders {
    notify owner "Order for {blend} would exceed $120. Please review."
    stop "over order limit"
  }

  let valid_orders_count = count of valid_orders
  append Beans { blend: blend, order_bags: order_bags, status: "ordered" }
  if valid_orders_count > 2 {
    notify owner "More than 2 blends ordered in this morning. Please review."
    stop "too many orders"
  }
}
```

