procedure HandleReturns {
  about "Process new return requests"
  policy HardwarePolicy
  sheet Returns "Returns" { return_no: Text, customer: Text, phone: Phone, amount: Money, bought: Date, opened: Bool, status: Text }
  trigger when new row r in Returns

  if r.opened {
    notify owner "Return {r.return_no} is opened. No refunds will be processed."
    stop "cannot refund opened items"
  }

  if days_between(r.bought, today()) > 30 {
    notify owner "Return {r.return_no} was bought {r.bought} (more than 30 days ago). Cannot process."
    stop "outside refund window"
  }

  if r.amount > $100.00 {
    notify owner "Refund request for {r.return_no} is {r.amount}, over $100. Please review."
    stop "over refund limit"
  }

  refund r.amount for r.return_no reason "refund request", ask owner first timeout 6 hours else stop "refund not approved"
  update r set status = "refunded"
  let m = draft sms to r.phone: "Hi {r.customer default 'there'}, your refund of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
  send ok
}
```

