procedure LaundryOrder {
  about "Order detergent from cheapest supplier"
  policy LaundryPolicy
  sheet Supplies "Supplies" { item: Text, on_hand: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every Friday at 07:00

  let all = fetch Supplies
  let detergent = filter all where item == "detergent"
  let cheapest = min(detergent, by: unit_cost)

  if is_empty(cheapest) {
    stop "no detergent row found"
  }

  let supplier = cheapest.supplier
  let cost = cheapest.unit_cost

  let order = 20  # fixed order quantity
  let total = order * cost

  let m = draft email to supplier subject "Detergent Order" body "Ordered 20 cases of detergent at ${cost} each. Total: ${total}."
  let ok = request approval of m from owner timeout 6 hours else stop "email not approved"
  send ok
}

