procedure ClinicWaitlistManagement {
  about "Manage waitlist when exam is cancelled"
  policy OptomPolicy
  sheet Cancellations "Cancellations" { event_id: Text, slot_text: Text }
  sheet Waitlist "Waitlist" { patient: Text, phone: Phone, joined: Date, status: Text }
  calendar Exams "Exams"

  trigger when new row r in Cancellations

  let exam = find Exams where event_id == r.event_id else skip
  cancel Cal event r.event_id

  let waitlist = find Waitlist where status == "waiting" and joined <= today()
  let earliest = min(waitlist by joined)

  if is_empty(earliest) {
    stop "no patients in waitlist"
  } else {
    let m = draft sms to earliest.phone: "Hi {earliest.patient default 'there'}, a spot has opened in {earliest.slot_text}. You are now 'offered'!"
    let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
    send ok
    update earliest set status = "offered"
  }
}
