procedure IceRefundProcessing {
  about "Process party cancellations with refund rules"
  policy IcePolicy
  sheet PartyCancellations "PartyCancellations" { ref: Text, host: Text, phone: Phone, deposit: Money, party_on: Date }
  trigger when new row r in PartyCancellations

  if days_between(r.party_on, today()) < 3 {
    notify owner "Party cancellation {r.ref} is less than 3 days away. No refund."
    stop "no refund allowed"
  }

  if r.deposit > $100 {
    notify owner "Refund request for {r.ref} is {r.deposit}. Please review."
    stop "deposit over $100"
  }

  if r.deposit <= $40 {
    refund r.deposit for r.ref reason "refund request", ask owner first timeout 6 hours else stop "refund not approved"
    update r set status = "refunded"
    let m = draft sms to r.phone: "Hi {r.host default 'there'}, your deposit of {r.deposit} is being refunded."
    let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
    send ok
  } else {
    notify owner "Refund request for {r.ref} is {r.deposit}. Please review."
    stop "deposit over $100"
  }
}
