procedure TicketStatusReport {
  about "Report tickets waiting parts for more than 10 days"
  policy RepairPolicy
  sheet Tickets "Tickets" { ticket: Text, customer: Text, email: Email, opened: Date, device: Text, status: Text, password: Text private }
  trigger every day at 09:00

  let all = fetch Tickets
  let overdue = filter all where days_between(opened, today()) > 10 and status == "waiting-parts"
  let n = summarize count of overdue
  if n > 30 {
    notify owner "Over 30 tickets are overdue. Only reporting the first 30."
    let first30 = overdue up to 30
    let msg = "Ticket numbers and devices for overdue tickets:\n"
    for each r in first30 {
      msg += f"{r.ticket}: {r.device}\n"
    }
    notify owner msg
  } else {
    let msg = "Overdue tickets (waiting-parts) for more than 10 days:\n"
    for each r in overdue {
      msg += f"{r.ticket}: {r.device}\n"
    }
    notify owner msg
  }
}
