procedure FloristStockCheck {
  about "Check and order flowers based on stock levels"
  policy FloristStockPolicy
  sheet Flowers "Flowers" { flower: Text, stems: Number, minimum: Number, reorder_qty: Number, grower: Text, unit_cost: Money }
  trigger every day at 16:00

  let all = fetch Flowers
  let needs_order = filter all where stems < minimum
  let orders = []
  let total_cost = 0

  for each r in needs_order up to 3 {
    let order = {
      flower: r.flower,
      grower: r.grower,
      quantity: r.reorder_qty,
      cost: r.unit_cost * r.reorder_qty
    }
    append orders with order
    total_cost += order.cost
  }

  if total_cost > $150 {
    notify owner "Total order cost exceeds $150. Please review."
    stop "over budget"
  }

  let msgs = draft each order in orders sms to order.grower: "Order of {order.quantity} {order.flower} (cost: ${order.cost})"
  let ok = request batch approval of msgs from owner timeout 2 hours else stop "batch not approved"
  send ok
}
