procedure FloristStockCheck {
  about "Check and order flowers based on stock levels"
  policy FloristStockPolicy
  sheet Flowers "Flowers" { flower: Text, stems: Number, minimum: Number, reorder_qty: Number, grower: Text, unit_cost: Money }
  trigger every Thursday at 16:00

  let all = fetch Flowers
  let needs_order = filter all where stems < minimum
  let orders = []
  let total_cost = 0

  for each r in needs_order {
    let order_cost = r.reorder_qty * r.unit_cost
    if order_cost > $150 {
      notify owner "Order of {r.flower} would cost {order_cost}, which exceeds $150. Please review."
      stop "over budget"
    }
    append orders { flower: r.flower, stems: r.stems, reorder_qty: r.reorder_qty, grower: r.grower, unit_cost: r.unit_cost }
    total_cost += order_cost
  }

  if len(orders) > 2 {
    notify owner "Handling more than 2 items. Only 2 items per run."
    stop "more than 2 items"
  }

  let msgs = draft each r in orders up to 2 sms to r.grower: "Order of {r.flower} with {r.reorder_qty} stems. Minimum: {r.minimum}."
  let ok = request approval of msgs from owner timeout 2 hours else stop "batch not approved"
  send ok
}
```

