procedure PhotostudioReminder {
  about "Send reminders to clients who haven't shot in 42 days"
  policy PhotostudioPolicy
  sheet Shoots "Shoots" { client: Text, email: Email, shoot_on: Date, status: Text, deposit: Money, venue_notes: Text private }
  trigger every day at 18:00

  let all = fetch Shoots
  let clients = filter all where days_between(shoot_on, today()) >= 42 and status != "cancelled"
  let n = summarize count of clients
  append Shoots "Outreach" { day: today(), campaign: "reminder", targeted: n }

  let msgs = draft each r in clients up to 15 sms to r.email: "Hi {r.client}, we've been waiting for your next shoot! We'd love to get you back on the schedule. Feel free to reach out if you need any help." 
  let ok = request batch approval of msgs from owner timeout 2 hours else stop "batch not approved"
  send ok
}

procedure PlumbingCustomerWelcome {
  about "Send welcome and check-in messages to new customers"
  policy PlumbingPolicy
  sheet Calls "Calls" { customer: Text, phone: Phone, visit_at: DateTime, status: Text, invoice: Money, alarm_code: Text private }
