procedure FloristDeliveryReminders {
  about "Send reminders to failed deliveries"
  policy FloristPolicy
  sheet Deliveries "Deliveries" { customer: Text, email: Email, deliver_on: Date, status: Text, price: Money, card_message: Text private }
  trigger every day at 10:00

  let all = fetch Deliveries
  let failed = filter all where status == "failed" and days_between(deliver_on, today()) <= 7
  let n = summarize count of failed

  if n == 0 {
    stop "no failed deliveries found"
  }

  let msgs = draft each r in failed up to 20 sms to r.email: "Hi {r.customer}, we're sorry for the delay. Let's reschedule your delivery for a new time. Please let us know when you're available."
  let ok = request batch approval of msgs from owner timeout 30 minutes else stop "batch not approved"
  send ok

  update failed set status = "contacted"
}

