  let valid = filter all where balance > 0 and status == "vaccinated" and days_between(vaccine_due, today()) > 5
  let n = summarize count of valid

  if n > 40 {
    notify owner "Maximum of 40 reminders per run. Skipping."
    stop "over limit"
  }

  for each r in valid up to 40 {
    let m = draft sms to r.phone: "Hi {r.owner default 'there'}, your pet's vaccination is 5+ days past due. Your balance is {r.balance}."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
  }
}
